<?php require "db.php";$d=input();$email=strtolower(trim($d["email"]??""));$role=$d["role"]??"";$s=$pdo->prepare("SELECT id,name,email,password,role,created_at FROM users WHERE email=? AND role=?");$s->execute([$email,$role]);$u=$s->fetch();if($u&&password_verify($d["password"]??"",$u["password"])){session_regenerate_id(true);unset($u["password"]);$_SESSION["user"]=$u;done(["success"=>true,"user"=>$u]);}http_response_code(401);done(["success"=>false,"message"=>"Invalid email, password or account type."]);?>